"use client";

import Image from "next/image";
import Link from "next/link";
import { ArrowUpRight } from "lucide-react";
import { motion, useTransform } from "framer-motion";
import { useAtelierScroll, useGentleTilt } from "./atelier-motion";

type CollectionItem = {
  title: string;
  subtitle: string;
  image: string;
  alt: string;
  detailImage?: string;
  portrait?: boolean;
};
function CollectionArtwork({
  collection,
  index,
}: {
  collection: CollectionItem;
  index: number;
}) {
  const { ref, reduced, progress } = useAtelierScroll();
  const tilt = useGentleTilt();
  const y = useTransform(
    progress,
    [0, 1],
    index % 2 === 0 ? [16, -16] : [22, -22],
  );
  const clip = useTransform(
    progress,
    [0, 0.27],
    ["inset(4% 0 0 0)", "inset(0% 0 0 0)"],
  );
  const imageY = useTransform(progress, [0, 1], ["-2%", "2%"]);
  const imageScale = useTransform(progress, [0, 1], [1.03, 1.04]);
  return (
    <article ref={ref} className={`gallery-work work-${index + 1}`}>
      <motion.div style={{ y: reduced ? 0 : y }}>
        <Link
          className="gallery-work-link"
          href={`/collections?category=${collection.title}`}
          {...tilt}
        >
          <motion.div
            className={`gallery-work-image${collection.portrait ? " gallery-portrait" : ""}`}
            style={{ clipPath: reduced ? "none" : clip }}
          >
            <motion.div
              className="gallery-image-plane"
              style={{
                y: reduced ? 0 : imageY,
                scale: reduced ? 1 : imageScale,
              }}
            >
              <Image
                src={`/images/${collection.image}.webp`}
                alt={collection.alt}
                fill
                sizes="(max-width: 600px) 85vw, 45vw"
              />
            </motion.div>
            <span className="gallery-detail" aria-hidden="true">
              <Image
                src={`/images/${collection.detailImage || collection.image}.webp`}
                alt=""
                fill
                sizes="(max-width: 600px) 85vw, 45vw"
              />
            </span>
            <span className="gallery-explore">
              Explore <ArrowUpRight size={16} />
            </span>
          </motion.div>
          <div className="gallery-work-title">
            <h3>{collection.title}</h3>
            <ArrowUpRight size={27} strokeWidth={1} />
          </div>
          <p>{collection.subtitle}</p>
        </Link>
      </motion.div>
    </article>
  );
}

export function CollectionStage({
  collections,
}: {
  collections: CollectionItem[];
}) {
  const { ref, reduced, progress } = useAtelierScroll();
  const titleY = useTransform(progress, [0, 1], [32, -45]);
  return (
    <section
      className="atelier-gallery"
      id="gallery"
      aria-labelledby="gallery-title"
      ref={ref}
    >
      <div className="gallery-introduction">
        <p className="eyebrow">Explore the collection</p>
        <div>
          <motion.h2 id="gallery-title" style={{ y: reduced ? 0 : titleY }}>
            Find your
            <br />
            everyday gold.
          </motion.h2>
          <p>
            From a single statement ring to a layered necklace, find jewellery
            that works with your wardrobe.
          </p>
        </div>
      </div>
      <div className="gallery-floor">
        {collections.map((c, i) => (
          <CollectionArtwork key={c.title} collection={c} index={i} />
        ))}
      </div>
      <div className="gallery-colophon">
        <Link href="/collections" className="text-link">
          View the complete collection <ArrowUpRight size={16} />
        </Link>
      </div>
    </section>
  );
}

